  _ = `%3$sから%2$sが始まります。%2$sへの参加をご希望の場合、日替わりスペシャルの割引期間は%1$s日以内にしてください。`,
  _ = `%3$sから%2$sが始まります。%2$sへの参加をご希望の場合、日替わりスペシャルの割引期間は%1$s日以内にしてください。`,
