  _ = `ゲームが日替わりスペシャルに招待されると、メールが届き、ゲームが上記のリストに表示されます。その時点からのプロセスの流れは次のとおりです。`,
  _ = `今後6か月以内で実施可能な日を選択してください。`,
  _ = `Steamホームページと該当するタグのページには24時間表示され、割引は選択した割引期間に応じて7～14日間適用されます。割引は選択した日の午前10時（PT）に開始されます。`,
