  _ = `選択した日替わりスペシャルと同じ月に他の割引を計画している場合、割引率を同等に保つようにしてください。日替わりスペシャルとしてゲームを取り上げる際、以前に行った割引と同じか、それよりも高い割引率であることが望ましいです。`,
