  _ = `現在の価格は、この通貨で通常設定できる価格を下回っています。この価格のままでも問題ありませんが、割引価格を最低取引金額以上に維持するために、ゲームの割引率には制限が生じます。`,
  _ = `%1$s： %2$s価格（%3$s）は、%2$sでの最小値%4$sを下回っています。数字の入力漏れなど誤りがないことを確認し、%4$s以上の値を入力してください。`,
  _ = `%1$s：%2$s価格（%3$s）は、現在公開されている価格（%4$s）を上回っています。定期更新サブスクリプションの価格は値上げできませんので、 %4$s以下の値を入力するか、値上げが必要な場合はSteamにお問い合わせください。`,
  _ = `許容範囲外の価格変更があと1件あります。`,
