  _ = `用途：スポットライトカプセルは、Steamホームページの上部および関連ストアハブに、Midweek DealやWeekend Dealのような特定のプロモーション用に表示されます。`,
  _ = `デザイン：スポットライトバナーは、プロモーションのタイプを説明するテキスト（例：Weekend Deal）およびプロモーションの終了日を、下部を覆う形で自動的に表示します。`,
  _ = `覆われる画像下部の範囲は、テキストの量や言語によって異なります。`,
  _ = `画像の下部4分の1には重要な要素は入れないでください。`,
  _ = `このカプセルでは主にゲームアートとロゴに焦点を当ててください。`,
  _ = `用途：スポットライト垂直カプセルは、ホームページの「割引＆イベント」セクションに表示されます。このアセットは、フランチャイズ／シリーズおよびパブリッシャーのセールイベントにのみ必要です。単一のゲームを参照するスポットライトには、そのゲームのストアの垂直カプセルが自動的に使用されます。`,
