  _ = `カプセルに重ねて表示されるスポットライトバナーのために、アートワークの上部にスペースを確保してください。`,
  _ = `ポップアップマーケティングメッセージ（%1$s）`,
  _ = `用途：SteamポップアップウィンドウとSteamのフロントページに表示`,
  _ = `デザイン：最良の結果を得るには、ロゴが確実に判読できるようにし、各種プロモーション（予約購入、配信中、近日登場など）へのコールアウトを含めてください。`,
  _ = `価格と行動喚起ボタンは、画像の下に自動で表示されます。`,
  _ = `ファイル（.jpg、.gif、.png）のサイズは5MB未満`,
  _ = `マーケティングメッセージはアニメーションをサポートしていますが、控えめなものである必要があります。アニメーションを使用する場合、上記のリンクのドキュメントを読み、アニメーションの仕様を順守する必要があります。`,
  _ = `アップデートのポップアップマーケティングメッセージ（%1$s）`,
