  _ = `デザイン：含める要素はアートとゲームロゴの2つのみにしてください`,
  _ = `アート：最良の結果を得るには、アップデートによって追加された新しいコンテンツ（新しいキーアート、スクリーンショット、新キャラクター、新機能など）を表すアートを使用してください。`,
  _ = `ロゴ：ゲームタイトルのメインロゴ、または該当する場合はゲームアップデートの公式ロゴを使用できます。ローカライズされたアセットのロゴに複数の言語バージョンがある場合は、それらも提供してください。`,
  _ = `この画像には追加のテキストを含めないでください。アップデートイベントと行動喚起に関する情報は、画像と一緒に自動的に表示されます。`,
  _ = `アニメーションのない静止画のみを使用してください。`,
