  _ = `デザイン：左／右／下の端は、ページの他の部分に適用されている単色へとフェードアウトまたはグラデーションで変化するようにしてください。詳細はテンプレートをよく確認してください。セールページロゴを使用しない場合は、この画像にはイベントロゴと日付を画像上部のセーフエリアに含める必要があります。`,
