  _ = `デザイン：この画像は重要ではなく、単にお知らせの文章にコンテキストと色を追加するためのものです。`,
  _ = `この画像は静止画で、5MB未満（.jpg、.png）である必要があります`,
  _ = `ストアページバナー`,
  _ = `用途：このバナーは、イベントに含まれる各ゲームの上部に表示されます。そのため、含まれるすべてのゲームの制作者から許可を得る必要があります。許可がないと、この機能を使用できません。`,
  _ = `デザイン：この画像には、イベントのロゴと日付を含める必要があり、プレイヤーが背景情報を理解できるように、行動喚起や短いキャッチフレーズを含めるのが理想的です。`,
  _ = `この画像は静止画で、5MB未満（.jpg、.png）である必要があります`,
  _ = `ストアページバナー（モバイル）`,
  _ = `用途：モバイル用のストアページバナーです。これは、幅が500ピクセル以下の画面で、デフォルトのストアページバナーに代わって表示されます。`,
