  _ = `アセットを提出`,
  _ = `アセットを提出...`,
  _ = `Valveにアセットが提出され、ここでの作業は完了です。提出されたアセットは、Steamチームのダッシュボードに自動的に表示され、プロモーション用のレビューと準備が行われます。`,
  _ = `アセットを提出しました！`,
  _ = `アセットが提出されました！これ以上のアセット関連アクションは必要ありません。`,
  _ = `以下をクリックしてプロモーション用アセットをValveに提出してください。提出すると、Steamチームが素材のレビューと準備を開始します。`,
  _ = `上記のURLが無効なため送信できません。`,
  _ = `アセットリクエストを送信するには、必須フィールドに入力してください。`,
  _ = `セールは%1$sに終了します`,
  _ = `重要！アセットの要件について`,
  _ = `以下のチェックリストを確認し、必要なアセットを提出すると、このプロモーションをSteamがサポートするすべての言語に翻訳することができます。`,
  _ = `各アセットのサイズは5MB未満`,
  _ = `アートワークはレイヤー化されたPhotoshop（PSD）ファイル`,
  _ = `可能な限り高解像度のメインゲーム／キャラクターアート（スマートオブジェクトを推奨）。それにより、必要に応じてこれらのアセットを、その他のSteamプロモーションアートの作成に再利用することができます。`,
  _ = `アートとは別のロゴ（スマートオブジェクトを推奨）。`,
  _ = `テキストはすべて、弊社チームがローカライズしやすいように、PSDドキュメント内の「text」フォルダーで編集可能な状態にしておいてください。`,
  _ = `使用したフォント（特にカスタムフォント）をすべて含めてください。`,
  _ = `テキストのスタイルやレイヤーはすべてPhotoshop内で管理してください。Illustratorなどの他のプログラムのファイルにはリンクしないでください。`,
  _ = `アニメーション付きのアセットの場合は、テキストやロゴを含まずシームレスにループするMP4やPNGシーケンスも提供してください。テキストは、弊社チームがローカライズしやすいように、別のレイヤーで用意して、アニメーションにしないでください。`,
  _ = `さらなる詳細や例、アニメーションアセットの具体的な内容については、<1>ストアプロモのグラフィックアセット</1>をご覧ください。`,
