  _ = `セールページのアートプレビューをアップロード`,
  _ = `セールページに関連する5つのアイテムのプレビューをローカリゼーション用に提出するには、下のアップローダーを使用してください。画像がサイズとトリミングの要件を満たしていることを確認してください。`,
