  _ = `最も早くリリースできる日：ゲームのビルドレビューが完了次第。`,
  _ = `最も早くリリースできる日：%1$s`,
  _ = `リリース日は最も早い場合でも、ストアページを「近日登場」として公開してから2週間後、またはアプリクレジット購入から21日後のうちどちらか遅い方になります。それを考慮して計画してください。`,
  _ = `リリース日は最も早い場合でも、ストアページを「近日登場」として公開してから2週間後になります。それを考慮して計画してください。`,
  _ = `Steamにおけるアプリケーションのリリース予定日を設定してください。すぐにリリースする予定がない場合は、最も有力なリリース日を設定してください。リリースを延期する必要がある場合は、以前に設定した日付の少なくとも2週間前に、ここで日付を変更してください。`,
  _ = `週末は、Valveがローンチ関連の問題に対応できないため、リリースを週末に設定することはできません。`,
  _ = `時刻はすべて米国太平洋時間（PT）です。`,
  _ = `現在、リリース予定日は「%1$s」に設定されています。この日付を変更する必要がある場合は、新しいリリース日と変更の理由を<1>Valveまでご連絡</1>ください。新しいリリース日は、確実にリリースできる日に設定してください。`,
  _ = `注意：近日登場ページが公開されているため、リリース日を変更すると、更新されたリリース日を反映して、ストアページが即時に公開されます。ストアページで保留中の編集内容もすべて公開されます。`,
  _ = `注意：設定できる最も早いリリース日は「%1$s」です。この日以降であれば、リリース予定日の設定にかかわらず、いつでもリリースボタンを押すことができます。`,
