  _ = `その日付は指定済みです。別の日を選んでください。`,
  _ = `リリース予定日`,
  _ = `公開日の表示`,
  _ = `この設定を使用して、ストアでのリリース日の表示方法を選択できます。`,
  _ = `形式を特定しない場合（例：「月、年」や「年」など）、ゲームは選択した期間のリスト内の最後に追加されます。`,
  _ = `リリース日に関するヘルプが必要ですか？<1>ドキュメント</1> | <2>Steamworksサポート</2>`,
  _ = `リリース日が選択されていません`,
  _ = `指定された日：`,
  _ = `設定解除`,
  _ = `顧客に表示される日：`,
  _ = `最も早いアドバンスアクセス日：`,
  _ = `アドバンスアクセス：`,
  _ = `このアプリのいずれかのパッケージの最も早いアドバンスアクセス日。`,
  _ = `体験版ウィッシュリストメール`,
  _ = `オプションはリリース後14日間利用可能`,
  _ = `ウィッシュリストのドキュメントを表示`,
  _ = `体験版を初めてリリースするときに、完全版のゲームをウィッシュリストに追加した人にSteamから通知するオプションがあります。このオプションは、体験版リリース後の最初の2週間に一度だけ利用できます。ウィッシュリスト通知は一度送信すると、2週間は次の通知を送信できないため、2週間以内にゲームをリリースする予定がある場合は利用しないほうが良いかもしれません。`,
  _ = `ベースゲームは2週間以内に%1$sでリリースされるように設定されています。ウィッシュリストメールを今送信すると、ウィッシュリストに追加済みのユーザーにはフルリリース時に通知メールが届かなくなります！`,
  _ = `%1$sにウィッシュリストのメールを送信しました。ウィッシュリストに追加した全員にメールが送信されるまでしばらく時間がかかる場合があります。`,
  _ = `ウィッシュリストのデータを表示`,
  _ = `（この通知は%1$sより後に消えます。）`,
  _ = `ウィッシュリストに追加した人にメールを送信`,
  _ = `ウィッシュリストメールを送信しました！`,
  _ = `ウィッシュリストメールを送信する際に問題が発生しました。後でもう一度お試しください。`,
  _ = `体験版に関する情報の取得中に問題が発生しました。しばらくしてからもう一度お試しください。`,
  _ = `ベースゲームと体験版の地域規制の種類が異なります。両方を許可リストか許可しないリストのどちらか一方に設定する必要があります。それぞれに別の設定はできません。ベースゲーム：%1$s。体験版：%2$s。`,
  _ = `ベースゲームと体験版の地域規制が異なります。ウィッシュリストメールは両方にアクセスできる顧客に送信されます。ベースゲーム：%1$s。体験版：%2$s。`,
  _ = `%1$sで許可`,
  _ = `%1$sでは許可なし`,
  _ = `制限なし`,
  _ = `警告！体験版はまだストアに表示されていません：`,
  _ = `<1>「ストアページを編集」＞「特殊設定」タブ ＞ 「関連する体験版」</1>で、体験版をベースゲームに関連付け、変更内容を必ず公開してください。これらの手順を完了した後、更新内容が反映されるまで数分かかる場合があります。`,
  _ = `ウィッシュリストに追加した人に体験版のリリース通知メールを送信しますか？`,
  _ = `あなたのゲームをウィッシュリストに追加したユーザーに体験版のリリースを通知するメールを送信しますか？`,
  _ = `重要な制限事項`,
  _ = `<1><2>体験版のリリースを通知するメールを送信できるのは1度だけです。</2>将来、体験版を無効化して再有効化した場合でも、ウィッシュリスト通知メールを送信できるのは1度だけです。</1><1><2>Steamは、2週間以内に複数のメールをプレイヤーに送信することはありません。</2>このメールを送信してから2週間以内にフルゲームをリリースする場合、体験版のメールを送信したプレイヤーにフルゲームのリリース通知メールは送信されません。その点を踏まえた上で、計画的に利用してください。</1>`,
  _ = `メールを送信`,
  _ = `取り消し`,
  _ = `近日登場タイトルの場合、この設定を使用して、ストアでのリリース予定の表示方法を選択できます。`,
  _ = `オプションを選択...`,
  _ = `近日登場の日付と表示の変更は、次回ストアページを公開したときに有効になります。`,
  _ = `公開の準備をする`,
  _ = `リリース日を選択してください`,
  _ = `公開日表示を選択してください。`,
  _ = `変更が保存されました`,
  _ = `コントローラサポートウィザード`,
  _ = `コントローラサポート情報`,
  _ = `ゲームのコントローラサポート状況をプレイヤーにわかりやすく説明するために、いくつかの簡単な質問を含むクイックウィザードを用意しました。

プレイヤーが、所有しているデバイスで快適に動作するゲームを見つけられるように、できる限り正確に回答して、このウィザードを完了してください。`,
  _ = `ステータス：ウィザードが開始されていません`,
  _ = `ステータス：コントローラサポートなし`,
  _ = `ウィザードを開始`,
  _ = `Steamは、コントローラのサポート状況についてご提供いただいた内容に基づいて以下の内訳を顧客に表示します。`,
  _ = `注：コントローラサポートは、ストアページが公開されるまでSteamライブラリに正しく表示されません。`,
  _ = `Xboxコントローラー`,
  _ = `PlayStationコントローラー`,
