  _ = `プレイテストパッケージのSteamキーをリクエストするには、このフォームを使用してください。すべてのSteamキーのリクエストは通常48～72時間以内に、Valveによって一件ずつ個別に審査されます。`,
  _ = `下のボックスを使用して、これらのキーの使用目的についてもお知らせください。これにより、ニーズに合った適切な量のキーがリクエストされていることを確認します。`,
