  _ = `アプリのクリエイターホームが設定されていません。クリエイターホームのドキュメントを確認して、<1>開発者ページ／パブリッシャーページ</1>、または<2>シリーズページ</2>をアプリ用にセットアップしてください。`,
  _ = `関連するクリエイターページを選択すると、そのページのアイテムがストアページに表示されます。このセクションはゲームの説明の下に表示されます。`,
