  _ = `制限されている地域：%1$s`,
  _ = `<1>コンテンツアンケート</1>を完了する必要があるようです。それによりレーティングの未設定による制限を解除できる可能性があります。`,
  _ = `ゲームレコーディング－タイムラインアイコンの管理`,
  _ = `ここで作成されたアイコンは、ゲーム録画のタイムライン上の特定の瞬間をマークするために使用できます。Steamのデフォルトのアイコンも使用できます。詳細についてはドキュメントを参照してください。`,
  _ = `アイコンを新規作成`,
  _ = `ゲームの録画タイムラインで使用する新しいアイコンを作成します`,
  _ = `タイムラインアイコンを新規作成`,
  _ = `（%1$s）アイコンを編集`,
  _ = `アイコン`,
  _ = `タイムラインプレビュー：`,
  _ = `一意の識別子`,
  _ = `API呼び出しで使用（最大%1$s文字）`,
  _ = `公開アイコンの一意の識別子は編集できません`,
  _ = `色`,
  _ = `一意の識別子を入力...`,
  _ = `API呼び出しで使用（最大%1$s文字）。小文字の英数字を使用してください。長さは3文字以上にしてください。「_」と「-」も使用できます。空白のスペースは使用できません。`,
  _ = `識別子に使用できない文字が含まれています。小文字の英数字を使用してください。長さは3文字以上にしてください。「_」と「-」も使用できます。空白のスペースは使用できません。`,
  _ = `識別子の先頭に、公式アイコン用の予約語「steam_」を使用することはできません。`,
  _ = `アイコンごとに、.pngまたは.svgファイルをアップロードし、API呼び出しで使用される一意の識別子を指定します。`,
  _ = `アイコン（.SVGまたは.PNGファイル）`,
  _ = `SVGアイコンは、36px x 36pxのビューボックスに表示されます。それに応じてアセットを作成してください。PNGは幅／高さが 24px～256pxの正方形のアセットである必要があります。`,
  _ = `SVGアイコンは、36px x 36pxのビューボックスに表示されます。それに応じてアセットを作成してください。PNGは幅／高さが 24px～256pxの正方形のアセットである必要があります。`,
  _ = `このSVGのビューボックスまたは幅／高さは%1$sであるため、正しく表示されない可能性があります。`,
